(()=>{const payloads=JSON.parse(document.getElementById('example-report-payloads').textContent),panel=document.getElementById('view-reports'),buttons=[...panel.querySelectorAll('[data-report-index]')],frame=document.getElementById('client-report-frame');function show(i,scroll){const bytes=Uint8Array.from(atob(payloads[i]),c=>c.charCodeAt(0));frame.srcdoc=new TextDecoder().decode(bytes);const title='Scenario '+(i+1);document.getElementById('client-report-title').textContent=title;frame.title=title+' report';buttons.forEach((b,j)=>{b.setAttribute('aria-pressed',String(j===i));b.classList.toggle('report-selected',j===i);b.setAttribute('aria-selected',String(j===i));b.tabIndex=j===i?0:-1});}buttons.forEach((b,i)=>b.addEventListener('click',()=>show(i,true)));show(0,false);})();